   375	static readstat_error_t sav_skip_value_label_record(sav_ctx_t *ctx) {
   376	    uint32_t label_count;
   377	    uint32_t rec_type;
   378	    uint32_t var_count;
   379	    readstat_error_t retval = READSTAT_OK;
   380	    readstat_io_t *io = ctx->io;
   381	    if (io->read(&label_count, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
   382	        retval = READSTAT_ERROR_READ;
   383	        goto cleanup;
   384	    }
   385	    if (ctx->bswap)
   386	        label_count = byteswap4(label_count);
   387	    int i;
   388	    for (i=0; i<label_count; i++) {
   389	        unsigned char unpadded_len = 0;
   390	        size_t padded_len = 0;
   391	        if (io->seek(8, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   392	            retval = READSTAT_ERROR_SEEK;
   393	            goto cleanup;
   394	        }
   395	        if (io->read(&unpadded_len, 1, io->io_ctx) < 1) {
   396	            retval = READSTAT_ERROR_READ;
   397	            goto cleanup;
   398	        }
   399	        padded_len = (unpadded_len + 8) / 8 * 8 - 1;
   400	        if (io->seek(padded_len, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   401	            retval = READSTAT_ERROR_SEEK;
   402	            goto cleanup;
   403	        }
   404	    }
   405	
   406	    if (io->read(&rec_type, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
   407	        retval = READSTAT_ERROR_READ;
   408	        goto cleanup;
   409	    }
   410	    if (ctx->bswap)
   411	        rec_type = byteswap4(rec_type);
   412	    
   413	    if (rec_type != 4) {
   414	        retval = READSTAT_ERROR_PARSE;
   415	        goto cleanup;
   416	    }
   417	    if (io->read(&var_count, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
   418	        retval = READSTAT_ERROR_READ;
   419	        goto cleanup;
   420	    }
   421	    if (ctx->bswap)
   422	        var_count = byteswap4(var_count);
   423	    
   424	    if (io->seek(var_count * sizeof(uint32_t), READSTAT_SEEK_CUR, io->io_ctx) == -1) {
   425	        retval = READSTAT_ERROR_SEEK;
   426	        goto cleanup;
   427	    }
   428	
   429	cleanup:
   430	    return retval;
   431	}
